-- Load into a DISPOSABLE database only, after the backend has created the
-- schema and the demo account. Never run against a shared database.
--
--   sqlite3 "$LMS_DB_PATH" ".read 04-联调基础数据.sql"
--
-- Idempotent: rows in the 101-199 ID band are deleted and re-inserted.
-- Seed rows (1-3) and the startup-created demo account are never touched.

BEGIN IMMEDIATE;

DELETE FROM tracking_events WHERE event_id BETWEEN 101 AND 199;
DELETE FROM shipment_items WHERE shipment_item_id BETWEEN 101 AND 199;
DELETE FROM shipments WHERE shipment_id BETWEEN 101 AND 199;
DELETE FROM items WHERE item_id BETWEEN 101 AND 199;
DELETE FROM hubs WHERE hub_id BETWEEN 101 AND 199;
DELETE FROM users WHERE user_id BETWEEN 101 AND 199;

-- users (7 rows)

-- hubs (3 rows)

-- items (6 rows)

-- shipments (5 rows)

-- shipment_items (6 rows)

-- tracking_events (8 rows)

COMMIT;

